ing? // JSON string or additional info\n  isEnabled       Boolean  @default(true)\n  isNetworkCamera Boolean  @default(false)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel TrainingRecord {\n  id           String    @id @default(uuid())\n  productId    String\n  taskUuid     String\n  labelName    String\n  modelName    String\n  config       String\n  status       String    @default(\"pending\")\n  progress     Float     @default(0)\n  totalEpochs  Int?\n  currentEpoch Int?\n  batchSize    Int?\n  learningRate Float?\n  latestIter   Int?\n  metrics      String    @default(\"[]\")\n  logs         String    @default(\"[]\")\n  startTime    DateTime?\n  endTime      DateTime?\n  hasBestModel Boolean   @default(false)\n  outputPath   String?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  // 重训相关字段\n  isRetrain     Boolean  @default(false) // 是否是重训任务\n  baseTaskUuid  String? // 基础模型的task_uuid（重训时使用）\n  pathId        String? // 路径ID（重训时使用）\n  taskChain     String   @default(\"\") // 任务血缘链\n  generation    Int      @default(0) // 第几代（0=原始训练，1=第一次重训...）\n  fpCount       Int      @default(0) // Dinomaly False Positive数量\n  fnCount       Int      @default(0) // False Negative数量\n  yoloFpCount   Int      @default(0) // YOLO False Positive数量\n  encoderName   String? // 编码器名称\n  decoderDepth  Int? // 解码器深度\n  epochs        Int? // 训练轮数\n  freezeEncoder Boolean? // 是否冻结编码器\n\n  @@unique([taskUuid, labelName])\n  @@index([productId])\n  @@index([taskUuid])\n  @@index([status])\n  @@index([isRetrain])\n  @@index([baseTaskUuid])\n}\n\nmodel AppSettings {\n  id             Int      @id @default(1)\n  dataPath       String\n  locale         String   @default(\"zh\")\n  backendMode    String   @default(\"local\")\n  backendIp      String   @default(\"localhost\")\n  backendUrl     String   @default(\"http://localhost:8000\")\n  backendPort    String   @default(\"8000\")\n  imageSettings  String?  @default(\"{\\\"exposure\\\":6084,\\\"gain\\\":1.2}\")\n  modbusSettings String?  @default(\"{\\\"enabled\\\":true,\\\"ip\\\":\\\"192.168.1.12\\\",\\\"port\\\":502,\\\"unitId\\\":1,\\\"buttonChannel\\\":1,\\\"resetChannel\\\":2,\\\"lightGreen\\\":0,\\\"lightYellow\\\":1,\\\"lightRed\\\":2,\\\"buzzer\\\":3}\")\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n}\n\n// ROI 图片记录表 - 用于重训管理\nmodel RoiImage {\n  id             String @id @default(uuid())\n  productId      String\n  sourceTaskUuid String // ROI来源的task_uuid（模型ID）\n  category       String // 缺陷类别\n\n  // 模型原始判断\n  modelIsAnomaly Boolean\n  // 用户修正后的判断\n  userIsAnomaly  Boolean\n  // 检测器来源\n  isYoloAnomaly  Boolean @default(false) // YOLO检测的异常（false=Dinomaly检测）\n  dinomalyScore  Float? // Dinomaly模型分数\n  // 'FP' = False Positive (模型NG, 用户OK) → 用于微调\n  // 'FN' = False Negative (模型OK, 用户NG) → 用于原型库\n  // 'NORMAL' = 判断一致或用户未修改\n  roiType        String  @default(\"NORMAL\")\n\n  filePath      String // 文件完整路径\n  fileName      String // 文件名\n  thumbnailPath String? // 缩略图路径\n\n  // 使用状态\n  usedInRetrain Boolean   @default(false)\n  usedTaskUuid  String? // 被用于哪个重训任务\n  usedAt        DateTime?\n\n  posId String? // 位置ID，用于FN图片的SSIM比对分组\n\n  // 支持链式重训\n  generation Int @default(0) // 第几代（0=原始训练，1=第一次重训...）\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([productId])\n  @@index([sourceTaskUuid])\n  @@index([roiType])\n  @@index([usedInRetrain])\n  @@index([usedTaskUuid])\n}\n",
